pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        address owner = c.Owner();
        vm.assume(seed != 0);
        address actor = address(uint160(seed));
        vm.assume(actor != owner);
        vm.assume(amount > 0);

