pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, address target, bytes calldata badData) public {
        // Restrict value to avoid overflow and keep the contract solvable.
        bound(value, 1, address(this).balance);
        vm.assume(value > 0);
        // Fuzz the target address but ensure it's not ourselves (to avoid complications).
        vm.assume(target != address(c) && target != address(this));
        // Use data that is guaranteed to call a non-existent function on plain EOAs,
        // so the low-level call returns false but does not revert.
        // We take the fuzzed calldata as-is (it may cause a revert if it matches a precompile selector, etc.,
        // but the property still holds in the revert case — we just need a case that succeeds but returns false).
        // Because EOA targets always return false without reverting for any calldata, the fuzzer will find
        // an input where target is an EOA and value > 0.
        vm.deal(address(c), 1 ether); // give the contract some existing balance
        uint256 balBefore = address(c).balance;
        vm.prank(address(c).Owner());
        vm.deal(address(c).Owner(), value);
        bool ok = true;
        try c.Command{value: value}(target, badData) {} catch { ok = false; }

        if (ok) {
            // After a successful Command call with value > 0, if the low-level call to an EOA returns false,
            // the value is not forwarded (it stays in the contract). The reference contract retains the value;
            // the buggy contract transfers its entire balance to Owner, leaving 0.
            // The invariant: contract balance must be >= value (since value stayed) and > 0.
            assertTrue(address(c).balance > 0);
        }
        // If the call reverted, no assertions needed; the interesting case is when it succeeds.
    }
}

