pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 preFund, address callee) public {
        // domain: amount and preFund are any value; callee must be a contract address,
        // but a fuzzed address is an EOA that always succeeds on call.
        // So we deploy a non-reverting helper and use its address as the mandatory adversarial callee.
        // This covers the case where the low-level call succeeds, which is the only case where the bug differs.

        vm.assume(preFund < type(uint256).max / 2); // prevent overflow
        vm.assume(amount < type(uint256).max / 2);

        // deploy a non-reverting helper that accepts ether and does nothing
        NonReverter helper = new NonReverter();

        // fund c with preFund to make it have a balance before Command
        if (preFund > 0) {
            vm.deal(address(c), preFund);
        }

        // Fund owner (this contract) with the amount to send
        address owner = c.Owner();
        vm.deal(owner, amount);

        // call Command as owner, sending amount, routing the external call to helper
        vm.prank(owner);
        (bool cmdOk, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, address(helper), "")
        );
        require(cmdOk, "Command reverted");

        // The call to helper always succeeds.
        // General rule: after any externally successful Command call, the contract's ETH balance must be 0.
        // The reference conforms: it only forwards msg.value, leaving its pre-existing balance unchanged,
        // but our assumption is that pre-existing balance should be zero because the contract shouldn't hold ETH
        // (except via receive(), which we don't use). The bug sends address(this).balance, potentially leaving
        // non-zero balance if preFund != amount.
        // Wait, the reference does NOT enforce zero balance; it just forwards msg.value. To make the rule hold
        // for the reference, we restrict the domain: we only call Command when the contract has no pre-existing ETH.
        // Thus we only send preFund=0. The bug still triggers when amount > 0 because the bug sends the entire
        // (zero) balance, which is zero, but the reference also sends zero. That doesn't differ.
        // Let's rethink.

        // The bug is in forwarding the entire balance vs msg.value. To expose the difference, the contract's
        // balance after Command must differ. For the reference, after a successful call, c.balance = preBalance (it kept its pre-existing funds).
        // For the bug, c.balance = 0 (it sent all). So the rule: after a successful Command call, c.balance == preBalance.
        // preBalance = c.balance before the call. That works without requiring preBalance=0.
        // So we need to snapshot pre-balance and assert post-balance equals that.
        // We can't snapshot dynamically inside the test easily, but we can compute expected post-balance based on preFund (sent before Command).
        // Since we setup preFund, preCommand balance = preFund.
        // After Command (reference): balance = preFund. After Command (bug): balance = 0 if msg.value > 0.
        // The assertion: after successful Command, c.balance == preFund.
        // That fails on bug because bug sends all, leaving 0.
        // This is exactly one of the already tried approaches ("After any externally successful call to Command, the contract's ETH balance must be identical to what it was before Command was called, because the call should only forward msg.value; the bug sends the entire balance and thus violates this invariant.") but it was rejected because it was already tried.
        // I need a different invariant.
    }
}

