import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 callValue, uint256 preFund) public {
        vm.assume(adr != address(0));
        vm.assume(callValue > 0);
        // Pre-fund the contract with some Ether to observe balance changes
        vm.deal(address(c), preFund);
        uint256 balanceBefore = address(c).balance;

        address caller = address(0xdead);
        vm.deal(caller, callValue);
        vm.prank(caller);
        try c.multiplicate{value: callValue}(adr) {} catch {}

        uint256 balanceAfter = address(c).balance;
        bool balanceDecreased = balanceAfter < balanceBefore;
